/// <FUN>
void FIUClass(int Fault_Type,byte Exp)
{
  int index,listindex,i,j,Time;
  dword DTClist[50];
  index=0;listindex=0;
  writeex(-3,0,"****************故障注入****************"); 
  for(j=0;j<elcount(Fault_array);j++)
    {
      if(Fault_array[j].Fault_Type == Fault_Type)
      {
        for(i=0;i<listindex;i++)
        { 
          if(Fault_array[j].DTC==DTClist[i])
          {break;}
        }
        if(i==listindex)
        {
          DTClist[listindex]=Fault_array[j].DTC;
          Time=_max(Time,Fault_array[j].time);         
          switch(Fault_Type)
           {
             case(Lose):
              writeex(-3,0,"----------------Lose %s----------------",Fault_array[j].Fault);
              testStep("故障注入","Lose %s",Fault_array[j].Fault);
               testDisableMsg(Fault_array[j].Fault);
               break;
             case(Dlc):
              writeex(-3,0,"----------------DLC %s----------------",Fault_array[j].Fault);
              testStep("故障注入","DLC %s",Fault_array[j].Fault);
              testSetMsgDlc(Fault_array[j].Fault,4);
               break;  
             case(Crc):
              writeex(-3,0,"----------------CRC %s----------------",Fault_array[j].Fault);
              testStep("故障注入","CRC %s",Fault_array[j].Fault);
              putValue(Fault_array[j].Fault,2);
               break;  
             case(Counter):
              writeex(-3,0,"----------------Counter %s----------------",Fault_array[j].Fault);
              testStep("故障注入","Counter %s",Fault_array[j].Fault);
              putValue(Fault_array[j].Fault,1);
               break;  
             case(Invalid):
              writeex(-3,0,"----------------Invalid %s----------------",Fault_array[j].Fault);
              testStep("故障注入","Invalid %s",Fault_array[j].Fault);
              setSignal(Fault_array[j].Fault,Fault_array[j].Value);
               break;  
             case(RowInvalid):
              writeex(-3,0,"----------------RowInvalid %s----------------",Fault_array[j].Fault);
              testStep("故障注入","RowInvalid %s",Fault_array[j].Fault);
              setRawSignal(Fault_array[j].Fault,Fault_array[j].Value);
               break;
           }          
          listindex++;
        }        
      }    
  }
    if(Exp!=0xF)
    {
      if(Time)
      {
       testWaitForTimeout(Time);
       TestStep_Read_Multi_DTC("",DTClist,listindex,Exp,1);
      }
    }
}
