    dword DTC_H,DTC_M,DTC_L;
    diagRequest  *  diagReq;
    diagSetTarget ("ABS_ESP");

    // 这样些可以不依赖dbc文件的定义，方便平台共用，也可以使用dbc中定义的诊断名称
    diagResize(diagReq,6);
    DiagSetPrimitiveByte(diagReq,0,0x19);
    DiagSetPrimitiveByte(diagReq,1,0x06);
    DiagSetPrimitiveByte(diagReq,2,DTC>>16); 
    DiagSetPrimitiveByte(diagReq,3,DTC>>8&0xFF); 
    DiagSetPrimitiveByte(diagReq,4,DTC&0xFF); 
    DiagSetPrimitiveByte(diagReq,5,OCC_Num); 

    //send and wait response
    TestReportWriteDiagObject(diagReq);    
    DiagSendRequest(diagReq);
    TestWaitForDiagRequestSent(diagReq, 150);    
    retVal = TestWaitForDiagResponse(diagReq, 1000);    //Get last response
    TestReportWriteDiagResponse(diagReq);   // write response to report
    //write("***************retVal:%d",retVal);

    if(retVal != 1)
    {
      testStepWarning("读取FDC","Response Code is %d",retVal);return 0;
    }

  return (byte)diagGetRespPrimitiveByte(diagReq,7);
}
