/* ===== 同步自模板的新增函数（auto merge）begin ===== */
// 重新装订定时器：装到“最早到期”的那个定时检测上；没有定时检测就撤掉
/// <Internal>
void ChkRearmTimer()
{
  int i;
  int found;
  dword now;
  dword next;

  now = timeNow() / 100;                  // timeNow() 单位 10us，/100 得 ms
  found = 0;
  next = 0;
  for (i = 0; i < mChkCount; i++)
  {
    if (mChkDeadlines[i] == 0) continue;
    if (found == 0 || mChkDeadlines[i] < next)
    {
      next = mChkDeadlines[i];
      found = 1;
    }
  }

  cancelTimer(timer_ChkDestroy);
  if (found == 0) return;
  if (next <= now)
    setTimer(timer_ChkDestroy, 1);
  else
    setTimer(timer_ChkDestroy, next - now);
}

// 给刚分配的槽位装订到期时刻（带 Timeout 的重载调用它，而不是直接 setTimer）
/// <Internal>
void ChkArmNew(dword Timeout)
{
  if (mChkLastIdx < 0 || mChkLastIdx >= mChkCount) return;
  mChkDeadlines[mChkLastIdx] = timeNow() / 100 + Timeout;
  ChkRearmTimer();
}

/// <ChkAssert>
// 全部收口：判定并释放**所有**检测（含定时检测），用于用例中途退出/收尾清理，
// 避免还没到期的定时检测残留到下一个用例
void ResetChkAll()
{
  int i;

  for (i = mChkCount - 1; i >= 0; i--)
  {
    if (mChkIds[i] != 0)
      ChkControl_Stop(mChkIds[i]);
    ChkReportAt(i);
    if (mChkIds[i] != 0)
      ChkControl_Destroy(mChkIds[i]);
    ChkSlotRemove(i);
  }
  cancelTimer(timer_ChkDestroy);
}

